"""CLI app generated by intpot."""
from __future__ import annotations


from pathlib import Path

import asyncio as _intpot_cli_asyncio
import inspect as _intpot_cli_inspect

import typer as _intpot_cli_typer

DAILY_RATE = 0.02

CAPACITY_GB = 20000

def storage_cost(size_gb: int, days: int, replicas: int) -> float:
    if size_gb * replicas > CAPACITY_GB:
        raise ValueError('replicated storage exceeds capacity')
    return round(size_gb * days * replicas * DAILY_RATE, 2)

app = _intpot_cli_typer.Typer(name='storage_quote', help='storage_quote — powered by intpot')
_intpot_required = object()


def _storage_quote_impl(
    size_gb: int = _intpot_required,
    days: int = 7,
    replicas: int = 2,
    receipt: str = '',
) -> dict:
    """Estimate storage cost within individual and replicated capacity limits."""
    if size_gb is _intpot_required:
        raise TypeError('Missing required argument: size_gb')
    cost = storage_cost(size_gb, days, replicas)
    result = {'cost': cost, 'size_gb': size_gb, 'days': days, 'replicas': replicas}
    if receipt:
        Path(receipt).write_text(str(result), encoding='utf-8')
    return result


@app.command(name='storage_quote')
def storage_quote(
    size_gb: int = _intpot_cli_typer.Argument(..., help='', min=1, max=10000),
    days: int = _intpot_cli_typer.Option(7, help='', min=1, max=365),
    replicas: int = _intpot_cli_typer.Option(2, help='', min=1, max=3),
    receipt: str = _intpot_cli_typer.Option('', help=''),
) -> None:
    """Estimate storage cost within individual and replicated capacity limits."""
    result = _storage_quote_impl(size_gb, days, replicas, receipt)
    if _intpot_cli_inspect.iscoroutine(result):
        result = _intpot_cli_asyncio.run(result)
    if result is not None:
        _intpot_cli_typer.echo(result)


if __name__ == "__main__":
    app()
